def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n == 1:
        return 'D' if history[-1][1] == 'D' else 'C'

    my = []
    op = []
    cc = 0
    suck = 0
    exploit = 0
    mutual = 0
    opp_c = 0

    for a, b in history:
        my.append(a)
        op.append(b)
        if b == 'C':
            opp_c += 1
        if a == 'C':
            if b == 'C':
                cc += 1
            else:
                suck += 1
        else:
            if b == 'C':
                exploit += 1
            else:
                mutual += 1

    opp_d = n - opp_c
    last_my, last_op = history[-1]

    recent5 = history[-5:] if n >= 5 else history
    recent3 = history[-3:] if n >= 3 else history
    recent5_opp_c = sum(1 for _, b in recent5 if b == 'C')
    recent3_opp_c = sum(1 for _, b in recent3 if b == 'C')

    resp_c = 0
    resp_d = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if op[i + 1] == 'C':
                resp_c += 1
            else:
                resp_d += 1

    fail_probe = False
    for i in range(n - 2):
        if (
            my[i] == 'D'
            and op[i] == 'C'
            and my[i + 1] == 'C'
            and op[i + 1] == 'D'
        ):
            fail_probe = True

    exploit_evidence = False
    if resp_c > 0 and resp_c >= 2 * resp_d:
        exploit_evidence = True
    if resp_c == 1 and resp_d == 0 and suck <= 2:
        exploit_evidence = True
    if fail_probe and resp_d >= resp_c:
        exploit_evidence = False

    if opp_c == 0:
        return 'D'
    if n >= 10 and opp_c <= 2 and opp_d >= n - 3:
        return 'D'

    if last_my == 'D' and last_op == 'D':
        if opp_c <= max(1, n // 20) or suck > max(3, n // 10) or recent3_opp_c == 0:
            return 'D'
        if exploit_evidence and suck > max(2, n // 20):
            return 'D'
        if opp_c * 2 >= n or recent5_opp_c >= 2:
            return 'C'
        return 'D'

    my_score = 3 * cc + 5 * exploit + mutual
    opp_score = 3 * cc + 5 * suck + mutual

    if last_op == 'C':
        if exploit_evidence:
            return 'D'

        if last_my == 'D':
            return 'C'

        if (
            n >= 4
            and not fail_probe
            and suck <= max(1, n // 30)
            and opp_d <= max(1, n // 30)
            and recent5_opp_c >= 3
        ):
            return 'D'

        if opp_d == 0 and suck == 0 and recent3_opp_c >= 2 and not fail_probe:
            return 'D'

        if (
            n >= 20
            and my_score + 4 < opp_score
            and opp_c * 4 >= n * 3
            and suck <= max(2, n // 20)
            and not fail_probe
        ):
            if rng.random() < 0.12:
                return 'D'

        return 'C'

    if exploit_evidence and suck > max(2, n // 20):
        return 'D'

    if suck <= max(1, n // 40) and opp_c * 4 >= n * 3 and recent5_opp_c >= 3:
        return 'C'

    if (
        exploit_evidence
        and opp_c * 4 >= n * 3
        and recent3_opp_c >= 2
        and suck <= max(2, n // 20)
    ):
        return 'C'

    if (
        n >= 20
        and opp_c * 2 >= n
        and suck <= max(2, n // 10)
        and recent5_opp_c >= 2
    ):
        return 'C'

    return 'D'
